#!/usr/bin/env python3
"""site_numbers.py — the home page's pipeline figures, GENERATED from the served Explorer data.

WHY. docs/index.html carried hand-typed numbers ("permit pipeline — 14,659 units", "905 Berkeley building
projects"). They were right on 2026-09-22 and wrong eight days later (1,095 projects; 14,946 units, 3,724 of them
already built), and "pipeline" silently included finished buildings. This script derives them from
docs/explorer_data.js and rewrites ONE marked block of index.html:

    <!-- BEGIN site_numbers data="<Generated stamp>" (generated by scripts/site_numbers.py — do not hand-edit) -->
    ...
    <!-- END site_numbers -->

The BEGIN marker records the export's "Generated:" stamp. scripts/deploy_gate.py compares it with the served
file's stamp, so a new export whose numbers were not regenerated cannot deploy.

Definitions (same population as the Explorer's "non-UC" figures: UC Berkeley projects are counted in beds, not
units, so they are left out):
  * built       = projects with status Completed (a certificate of occupancy), units summed;
  * not yet built = every other project (review, entitled, permitted, under construction, inactive);
  * completions per year = units in Completed projects by the year of their certificate of occupancy.

Run after every export promotion:  python3 scripts/site_numbers.py
"""
import collections
import html
import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DATA = os.path.join(ROOT, 'docs', 'explorer_data.js')
PAGE = os.path.join(ROOT, 'docs', 'index.html')
BEGIN_RE = re.compile(r'<!-- BEGIN site_numbers.*?-->.*?<!-- END site_numbers -->', re.S)


def load():
    s = open(DATA).read()
    stamp = re.search(r'Generated:\s*(.+)', s).group(1).strip()
    return stamp, json.loads(s[s.index('{'):s.rindex('}') + 1])


def figures(d):
    P = [p for p in d['projects'] if not p.get('is_uc_project')]
    units = lambda p: int(p.get('units') or 0)
    done = [p for p in P if p.get('status') == 'Completed']
    todo = [p for p in P if p.get('status') != 'Completed']
    by_year = collections.Counter()
    for p in done:
        by_year[str(p.get('co_date') or '')[:4]] += units(p)
    assert '' not in by_year, 'a Completed project has no certificate-of-occupancy date'
    latest = max(str(p.get('co_date')) for p in done)[:10]
    return dict(projects=len(P), built=sum(map(units, done)), not_built=sum(map(units, todo)),
                n_not_built=len(todo), first_year=min(by_year), by_year=dict(sorted(by_year.items())), latest=latest)


def render(stamp, f):
    import datetime
    yrs = list(f['by_year'])
    last = datetime.date.fromisoformat(f['latest'])
    through = f"{last.strftime('%B')} {last.day}"
    chips = ''.join(
        f'<div style="flex: 0 0 auto; min-width: 3.6rem; padding: .25rem .35rem; background: #eef4fb; border-radius: 6px;">'
        f'<div style="font-size: .75rem; color: #4a5568;">{y}{"*" if y == yrs[-1] else ""}</div>'
        f'<div style="font-weight: 700; font-variant-numeric: tabular-nums;">{f["by_year"][y]:,}</div></div>'
        for y in yrs)
    return f'''<!-- BEGIN site_numbers data="{html.escape(stamp)}" (generated by scripts/site_numbers.py — do not hand-edit) -->
  <p style="margin: 0.45rem 0 0.2rem; text-align: center;">
    <a href="explorer.html" class="hero-cta">See Berkeley&rsquo;s permit pipeline &mdash; {f['not_built']:,} units not yet built, {f['built']:,} built since {f['first_year']} &rarr;</a>
  </p>
  <p style="margin: 0.45rem 0 0; text-align: center;">
    <a href="explorer.html?tab=projects" class="hero-cta">See {f['projects']:,} Berkeley building projects &rarr;</a>
  </p>
  <div role="group" aria-label="Units completed each year" style="max-width: 40rem; margin: 0.7rem auto 0; text-align: center; color: #1a365d;">
    <div style="color: #4a5568; font-size: 0.85rem; margin-bottom: .3rem;">Units completed each year (certificates of occupancy)</div>
    <div style="display: flex; flex-wrap: wrap; justify-content: center; gap: .35rem;">{chips}</div>
    <div style="margin-top: .3rem; color: #718096; font-size: 0.75rem;">*{yrs[-1]} through {through}. Excludes UC Berkeley, counted in beds. From the Explorer&rsquo;s data, updated {html.escape(stamp[:10])}.</div>
  </div>
  <!-- END site_numbers -->'''


def main():
    stamp, d = load()
    f = figures(d)
    page = open(PAGE).read()
    block = render(stamp, f)
    if BEGIN_RE.search(page):
        new = BEGIN_RE.sub(lambda m: block, page, count=1)
    else:   # first run: replace the two hand-typed call-to-action paragraphs
        old = re.compile(r'  <p style="margin: 0\.45rem 0 0\.2rem; text-align: center;">\s*<a href="explorer\.html" class="hero-cta">.*?</a>\s*</p>\s*'
                         r'<p style="margin: 0\.45rem 0 0; text-align: center;">\s*<a href="explorer\.html\?tab=projects" class="hero-cta">.*?</a>\s*</p>', re.S)
        assert len(old.findall(page)) == 1, 'could not find the two hand-typed call-to-action lines exactly once'
        new = old.sub(lambda m: block, page, count=1)
    open(PAGE, 'w').write(new)
    print(f"site_numbers: {f['projects']:,} projects · {f['not_built']:,} units not yet built ({f['n_not_built']} projects) · "
          f"{f['built']:,} built since {f['first_year']} · by year {f['by_year']} · data {stamp}")


if __name__ == '__main__':
    sys.exit(main())
